"""
theme.py — Celestial Fantasy UI Theme for MyLife Dashboard
"""
import streamlit as st

def inject_theme():
    st.markdown("""
    <style>
    @import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;0,500;1,300;1,400&family=Cinzel:wght@400;500&family=Raleway:wght@300;400;500&display=swap');

    :root {
        --blush:      #f2d7e0;
        --rose:       #e8b4c4;
        --dusty-pink: #d4899f;
        --mauve:      #b97a95;
        --lavender:   #c9b8d8;
        --soft-lilac: #e8dff0;
        --deep-plum:  #7a5c7a;
        --midnight:   #3d2b4a;
        --cream:      #fdf6f0;
        --star-gold:  #e8d5a3;
        --glow:       rgba(232, 180, 196, 0.35);
    }

    /* ── GLOBAL BACKGROUND ── */
    .stApp {
        background: linear-gradient(135deg,
            #f5e6ef 0%,
            #ede0f0 25%,
            #e8dff5 50%,
            #f0e6f5 75%,
            #f5dfe8 100%);
        background-attachment: fixed;
        font-family: 'Raleway', sans-serif;
    }

    /* ── HIDE STREAMLIT CHROME ── */
    #MainMenu, footer, header { visibility: hidden; }
    .stDeployButton { display: none; }

    /* ── SIDEBAR ── */
    [data-testid="stSidebar"] {
        background: linear-gradient(180deg, #3d2b4a 0%, #5c3d6e 50%, #7a5c7a 100%) !important;
        border-right: 1px solid rgba(232, 180, 196, 0.3);
    }
    [data-testid="stSidebar"] * {
        color: #f2d7e0 !important;
        font-family: 'Raleway', sans-serif !important;
    }
    [data-testid="stSidebar"] .stRadio label {
        color: #e8dff0 !important;
        font-size: 0.95rem;
        letter-spacing: 0.04em;
    }
    [data-testid="stSidebar"] button {
        background: rgba(232, 180, 196, 0.15) !important;
        border: 1px solid rgba(232, 180, 196, 0.4) !important;
        color: #f2d7e0 !important;
        border-radius: 20px !important;
    }
    [data-testid="stSidebar"] button:hover {
        background: rgba(232, 180, 196, 0.3) !important;
    }

    /* ── MAIN HEADINGS ── */
    h1, h2, h3 {
        font-family: 'Cinzel', serif !important;
        color: var(--deep-plum) !important;
        letter-spacing: 0.06em;
    }
    h1 {
        font-size: 2rem !important;
        background: linear-gradient(135deg, #7a5c7a, #b97a95, #c9b8d8);
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
        background-clip: text;
    }
    h2 { font-size: 1.3rem !important; color: var(--mauve) !important; }
    h3 { font-size: 1.1rem !important; }

    /* ── METRIC BOXES ── */
    [data-testid="stMetric"] {
        background: linear-gradient(135deg, rgba(253,246,240,0.9), rgba(232,223,240,0.9)) !important;
        border: 1px solid rgba(185, 122, 149, 0.3) !important;
        border-radius: 16px !important;
        padding: 18px !important;
        box-shadow: 0 4px 20px rgba(122, 92, 122, 0.12) !important;
        backdrop-filter: blur(10px);
    }
    [data-testid="stMetricLabel"] {
        font-family: 'Cinzel', serif !important;
        font-size: 0.75rem !important;
        color: var(--mauve) !important;
        letter-spacing: 0.1em !important;
        text-transform: uppercase;
    }
    [data-testid="stMetricValue"] {
        font-family: 'Cormorant Garamond', serif !important;
        font-size: 2rem !important;
        color: var(--deep-plum) !important;
        font-weight: 500;
    }

    /* ── FORMS ── */
    .stForm {
        background: linear-gradient(135deg, rgba(253,246,240,0.85), rgba(240,230,245,0.85)) !important;
        border: 1px solid rgba(185, 122, 149, 0.25) !important;
        border-radius: 20px !important;
        padding: 28px !important;
        box-shadow: 0 8px 32px rgba(122, 92, 122, 0.1), inset 0 1px 0 rgba(255,255,255,0.6) !important;
        backdrop-filter: blur(12px);
    }

    /* Input boxes */
    .stTextInput input, .stNumberInput input, .stDateInput input {
        background: rgba(253, 246, 240, 0.8) !important;
        border: 1px solid rgba(185, 122, 149, 0.4) !important;
        border-radius: 25px !important;
        color: var(--midnight) !important;
        font-family: 'Raleway', sans-serif !important;
        padding: 10px 18px !important;
        transition: all 0.3s ease !important;
    }
    .stTextInput input:focus, .stNumberInput input:focus {
        border-color: var(--mauve) !important;
        box-shadow: 0 0 0 3px rgba(185, 122, 149, 0.2) !important;
        background: rgba(253, 246, 240, 1) !important;
    }

    /* Selectboxes */
    .stSelectbox > div > div {
        background: rgba(253, 246, 240, 0.85) !important;
        border: 1px solid rgba(185, 122, 149, 0.4) !important;
        border-radius: 25px !important;
        font-family: 'Raleway', sans-serif !important;
        color: var(--midnight) !important;
    }

    /* ── BUTTONS ── */
    .stButton > button {
        background: linear-gradient(135deg, #c9b8d8, #b97a95) !important;
        color: white !important;
        border: none !important;
        border-radius: 25px !important;
        font-family: 'Cinzel', serif !important;
        font-size: 0.85rem !important;
        letter-spacing: 0.12em !important;
        padding: 10px 28px !important;
        box-shadow: 0 4px 15px rgba(185, 122, 149, 0.35) !important;
        transition: all 0.3s ease !important;
    }
    .stButton > button:hover {
        background: linear-gradient(135deg, #b97a95, #9a6080) !important;
        box-shadow: 0 6px 20px rgba(185, 122, 149, 0.5) !important;
        transform: translateY(-2px) !important;
    }

    .stFormSubmitButton > button {
        background: linear-gradient(135deg, #b97a95, #7a5c7a) !important;
        color: var(--cream) !important;
        border-radius: 25px !important;
        font-family: 'Cinzel', serif !important;
        letter-spacing: 0.15em !important;
        padding: 12px 36px !important;
        font-size: 0.9rem !important;
        box-shadow: 0 4px 20px rgba(122, 92, 122, 0.4) !important;
        border: none !important;
        width: 100% !important;
        transition: all 0.3s ease !important;
    }
    .stFormSubmitButton > button:hover {
        background: linear-gradient(135deg, #9a6080, #5c3d6e) !important;
        box-shadow: 0 6px 25px rgba(122, 92, 122, 0.55) !important;
        transform: translateY(-2px) !important;
    }

    /* ── TABS ── */
    .stTabs [data-baseweb="tab-list"] {
        background: rgba(240, 230, 245, 0.6) !important;
        border-radius: 30px !important;
        padding: 4px !important;
        gap: 4px !important;
        border: 1px solid rgba(185, 122, 149, 0.2) !important;
    }
    .stTabs [data-baseweb="tab"] {
        background: transparent !important;
        border-radius: 25px !important;
        color: var(--mauve) !important;
        font-family: 'Cinzel', serif !important;
        font-size: 0.78rem !important;
        letter-spacing: 0.06em !important;
        border: none !important;
    }
    .stTabs [aria-selected="true"] {
        background: linear-gradient(135deg, #c9b8d8, #b97a95) !important;
        color: white !important;
        box-shadow: 0 2px 10px rgba(185, 122, 149, 0.4) !important;
    }

    /* ── DATAFRAMES ── */
    .stDataFrame {
        border: 1px solid rgba(185, 122, 149, 0.25) !important;
        border-radius: 16px !important;
        overflow: hidden !important;
        box-shadow: 0 4px 20px rgba(122, 92, 122, 0.08) !important;
    }

    /* ── ALERTS ── */
    .stSuccess {
        background: linear-gradient(135deg, rgba(200,232,200,0.7), rgba(232,255,232,0.7)) !important;
        border: 1px solid rgba(140, 200, 140, 0.5) !important;
        border-radius: 12px !important;
    }
    .stError {
        background: linear-gradient(135deg, rgba(232,180,180,0.7), rgba(255,220,220,0.7)) !important;
        border: 1px solid rgba(200,140,140,0.5) !important;
        border-radius: 12px !important;
    }
    .stWarning {
        background: linear-gradient(135deg, rgba(232,220,180,0.7), rgba(255,245,200,0.7)) !important;
        border: 1px solid rgba(200,180,140,0.5) !important;
        border-radius: 12px !important;
    }
    .stInfo {
        background: linear-gradient(135deg, rgba(200,210,232,0.7), rgba(220,230,255,0.7)) !important;
        border: 1px solid rgba(160,180,220,0.5) !important;
        border-radius: 12px !important;
    }

    /* ── EXPANDERS ── */
    .stExpander {
        background: rgba(253, 246, 240, 0.7) !important;
        border: 1px solid rgba(185, 122, 149, 0.25) !important;
        border-radius: 16px !important;
    }

    hr { border-color: rgba(185, 122, 149, 0.2) !important; }

    /* Kill any default img borders/outlines globally */
    img { border: none !important; outline: none !important; box-shadow: none !important; }

    .stRadio label {
        color: var(--deep-plum) !important;
        font-family: 'Raleway', sans-serif !important;
    }

    .stCaption, caption {
        color: var(--mauve) !important;
        font-style: italic;
    }

    ::-webkit-scrollbar { width: 6px; }
    ::-webkit-scrollbar-track { background: rgba(240,230,245,0.5); }
    ::-webkit-scrollbar-thumb {
        background: linear-gradient(180deg, #c9b8d8, #b97a95);
        border-radius: 10px;
    }
    </style>
    """, unsafe_allow_html=True)


def login_page_css():
    """Full-screen, no-scroll auth layout. Everything fits in 100vh."""
    import streamlit as st
    st.markdown("""
    <style>
    /* ── LOCK: everything in one screen, zero scroll ── */
    html, body,
    .stApp,
    [data-testid="stAppViewContainer"],
    [data-testid="stAppViewBlockContainer"],
    .main, .block-container {
        overflow: hidden !important;
        height: 100vh !important;
        max-height: 100vh !important;
        margin: 0 !important;
        padding: 0 !important;
    }

    /* ── CENTRE column ── */
    [data-testid="stAppViewBlockContainer"] {
        display: flex !important;
        flex-direction: column !important;
        align-items: center !important;
        justify-content: center !important;
    }
    [data-testid="stAppViewBlockContainer"] > div {
        width: 100% !important;
        max-width: 420px !important;
        display: flex !important;
        flex-direction: column !important;
        align-items: center !important;
    }

    /* ── Hide the inject_theme star row ── */
    .stApp::before { display: none !important; }

    /* ── Page title ── */
    h1 {
        text-align: center !important;
        margin: 0 0 4px 0 !important;
        font-size: 1.5rem !important;
        width: 100% !important;
    }

    /* ── Auth card ── */
    .stForm {
        width: 360px !important;
        max-width: 90vw !important;
        margin: 0 auto !important;
        background: linear-gradient(145deg,
            rgba(253,246,240,0.97) 0%,
            rgba(240,228,248,0.97) 100%) !important;
        border: 1px solid rgba(185,122,149,0.35) !important;
        border-radius: 22px !important;
        padding: 18px 24px 14px !important;
        box-shadow: 0 14px 40px rgba(122,92,122,0.15),
                    inset 0 2px 0 rgba(255,255,255,0.75) !important;
    }

    /* ── Compact inputs ── */
    .stTextInput input {
        padding: 6px 14px !important;
        width: 100% !important;
        box-sizing: border-box !important;
    }
    .stForm .stTextInput,
    .stForm .stTextInput input {
        width: 100% !important;
        box-sizing: border-box !important;
    }

    /* ── Buttons ── */
    .stButton {
        display: flex !important;
        justify-content: center !important;
        margin-top: 5px !important;
        margin-bottom: 0 !important;
    }
    .stButton > button {
        width: 360px !important;
        max-width: 90vw !important;
        padding: 7px 24px !important;
        font-size: 0.82rem !important;
    }

    /* ── Ghost secondary button ── */
    [data-testid="baseButton-secondary"] {
        background: transparent !important;
        border: 1.5px solid rgba(185,122,149,0.5) !important;
        color: var(--mauve) !important;
        box-shadow: none !important;
    }
    [data-testid="baseButton-secondary"]:hover {
        background: rgba(185,122,149,0.08) !important;
        transform: translateY(-1px) !important;
    }

    /* ── Compact 2-col register inputs ── */
    .stForm [data-testid="column"] .stTextInput input {
        padding: 6px 12px !important;
    }

    /* ── Hide scrollbar ── */
    ::-webkit-scrollbar { display: none !important; width: 0 !important; }
    * { scrollbar-width: none !important; }
    </style>
    """, unsafe_allow_html=True)


def panda_banner():
    """Pandas with glassmorphism quote card — compact to fit on screen."""
    import streamlit as st

    L = ""
    R = ""

    wrapper_open = (
        '<div style="'
        'display:flex;align-items:center;justify-content:center;'
        'max-width:360px;margin:6px auto 0 auto;gap:0;position:relative;'
        '">'
    )

    # Left panda
    left_img = (
        '<img src="data:image/png;base64,' + L + '" '
        'style="'
        'width:110px;flex-shrink:0;position:relative;z-index:2;'
        'margin-right:-14px;'
        'border:none !important;outline:none !important;'
        'box-shadow:none !important;display:block;'
        'filter:drop-shadow(1px 3px 6px rgba(122,92,122,0.15));'
        '" />'
    )

    # Glassmorphism quote — no hard border sides, blurred so pandas show through
    quote_card = (
        '<div style="'
        'flex:1;text-align:center;padding:12px 14px;'
        'font-family:Cormorant Garamond,serif;font-style:italic;'
        'font-size:0.82rem;line-height:1.6;color:#9a6080;'
        'background:rgba(255,245,250,0.45);'
        'border-top:1px solid rgba(185,122,149,0.3);'
        'border-bottom:1px solid rgba(185,122,149,0.3);'
        'border-left:none;border-right:none;'
        'border-radius:0;'
        'backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);'
        'position:relative;z-index:1;'
        '">'
        '&ldquo;Balance your books.<br>Open your mind.&rdquo;'
        '</div>'
    )

    # Right panda
    right_img = (
        '<img src="data:image/png;base64,' + R + '" '
        'style="'
        'width:110px;flex-shrink:0;position:relative;z-index:2;'
        'margin-left:-14px;'
        'border:none !important;outline:none !important;'
        'box-shadow:none !important;display:block;'
        'filter:drop-shadow(-1px 3px 6px rgba(122,92,122,0.15));'
        '" />'
    )

    wrapper_close = '</div>'

    st.markdown(
        wrapper_open + left_img + quote_card + right_img + wrapper_close,
        unsafe_allow_html=True
    )